// Parsea el mensaje de RabbitMQ y descarga el raw desde MinIO
const msg = JSON.parse($input.item.json.content || JSON.stringify($input.item.json));
const date = msg.date;

// Construye las URLs de descarga desde MinIO
const baseUrl = 'http://minio:9000/madrid-openmeteo-environment';
const rawUrl = `${baseUrl}/raw/ingesta/date=${date}/raw_${date}.json`;

return [{ json: { date, rawUrl } }];

// Transforma los datos raw en tablas clean (weather y air)
const date = $('Code in JavaScript').item.json.date;
const raw = $input.item.json;

const weather = raw.weather;
const air = raw.air_quality;

// Genera filas clean para weather (24 filas horarias)
const weatherRows = weather.hourly.time.map((time, i) => ({
  source: 'open_meteo',
  dataset: 'historical_weather',
  date: date,
  time: time,
  latitude: weather.latitude,
  longitude: weather.longitude,
  temperature_2m: weather.hourly.temperature_2m[i] ?? '',
  temperature_2m_unit: weather.hourly_units?.temperature_2m ?? '°C',
  precipitation: weather.hourly.precipitation[i] ?? '',
  precipitation_unit: weather.hourly_units?.precipitation ?? 'mm'
}));

// Genera filas clean para air quality (24 filas horarias)
const airRows = air.hourly.time.map((time, i) => ({
  source: 'open_meteo',
  dataset: 'air_quality',
  date: date,
  time: time,
  latitude: air.latitude,
  longitude: air.longitude,
  ozone: air.hourly.ozone[i] ?? '',
  ozone_unit: air.hourly_units?.ozone ?? 'μg/m³',
  carbon_dioxide: air.hourly.carbon_dioxide[i] ?? '',
  carbon_dioxide_unit: air.hourly_units?.carbon_dioxide ?? 'ppm'
}));

// Genera tabla processed en formato largo (96 filas: 24h x 4 variables)
const longRows = [];
weatherRows.forEach(row => {
  ['temperature_2m', 'precipitation'].forEach(variable => {
    longRows.push({
      source: row.source, dataset: row.dataset, date: row.date, time: row.time,
      latitude: row.latitude, longitude: row.longitude,
      variable, value: row[variable], unit: row[variable + '_unit']
    });
  });
});
airRows.forEach(row => {
  ['ozone', 'carbon_dioxide'].forEach(variable => {
    longRows.push({
      source: row.source, dataset: row.dataset, date: row.date, time: row.time,
      latitude: row.latitude, longitude: row.longitude,
      variable, value: row[variable], unit: row[variable + '_unit']
    });
  });
});

return [{ json: { date, weatherRows, airRows, longRows } }];

// Convierte weatherRows a CSV
const { date, weatherRows } = $input.item.json;
const fields = ['source','dataset','date','time','latitude','longitude','temperature_2m','temperature_2m_unit','precipitation','precipitation_unit'];
const csv = [fields.join(','), ...weatherRows.map(r => fields.map(f => r[f] ?? '').join(','))].join('\n');
return [{ json: { date, csv, fileName: `weather_hourly.csv`, path: `clean/historical_weather_hourly/date=${date}/weather_hourly.csv` } }];

// Convierte airRows a CSV
const { date, airRows } = $('Code in JavaScript1').item.json;
const fields = ['source','dataset','date','time','latitude','longitude','ozone','ozone_unit','carbon_dioxide','carbon_dioxide_unit'];
const csv = [fields.join(','), ...airRows.map(r => fields.map(f => r[f] ?? '').join(','))].join('\n');
return [{ json: { date, csv, fileName: `air_quality_hourly.csv`, path: `clean/air_quality_hourly/date=${date}/air_quality_hourly.csv` } }];

// Convierte longRows (processed) a CSV
const { date, longRows } = $('Code in JavaScript1').item.json;
const fields = ['source','dataset','date','time','latitude','longitude','variable','value','unit'];
const csv = [fields.join(','), ...longRows.map(r => fields.map(f => r[f] ?? '').join(','))].join('\n');
return [{ json: { date, csv, fileName: `environment_observations_long.csv`, path: `processed/environment_observations_long/date=${date}/environment_observations_long.csv` } }];
